# 3. BUILD AND SAVE THE DATASET (NO SPLIT)
# ────────────────────────────────────────────────────────────────────────
from command_schema import COMMANDS

data = []
# Map 1:1 with exactly what is in the dataset map, no multiplication
for token, utterances in dataset_map.items():
    for utt in utterances:
        data.append({'input': utt, 'target': COMMANDS[token]})

random.seed(42)
random.shuffle(data)

# NO SPLIT: Save everything directly into valnewvalue.json
with open('valnewvalue.json', 'w', encoding='utf-8') as f: 
    json.dump(data, f, ensure_ascii=False, indent=2)

print(f"✅ Generated command_schema.py!")
